vec3 mod289(vec3 x) {
  return x - floor(x * (1.0 / 289.0)) * 289.0;
}

vec2 mod289(vec2 x) {
  return x - floor(x * (1.0 / 289.0)) * 289.0;
}

vec3 permute(vec3 x) {
  return mod289(((x * 34.0) + 1.0) * x);
}

float snoise(vec2 v) {
  const vec4 C = vec4(0.211324865405187,  // (3.0 - sqrt(3.0)) / 6.0
                      0.366025403784439,  // 0.5 * (sqrt(3.0) - 1.0)
                     -0.577350269189626,  // -1.0 + 2.0 * C.x
                      0.024390243902439); // 1.0 / 41.0
  vec2 i = floor(v + dot(v, C.yy));
  vec2 x0 = v - i + dot(i, C.xx);

  vec2 i1;
  i1 = (x0.x > x0.y) ? vec2(1.0, 0.0) : vec2(0.0, 1.0);

  vec4 x12 = x0.xyxy + C.xxzz;
  x12.xy -= i1;

  i = mod289(i);
  vec3 p = permute(permute(i.y + vec3(0.0, i1.y, 1.0))
                         + i.x + vec3(0.0, i1.x, 1.0));

  vec3 m = max(0.5 - vec3(dot(x0, x0), dot(x12.xy, x12.xy), dot(x12.zw, x12.zw)), 0.0);
  m = m * m;
  m = m * m;

  vec3 x = 2.0 * fract(p * C.www) - 1.0;
  vec3 h = abs(x) - 0.5;
  vec3 ox = floor(x + 0.5);
  vec3 a0 = x - ox;

  m *= 1.79284291400159 - 0.85373472095314 * (a0 * a0 + h * h);

  vec3 g;
  g.x = a0.x * x0.x + h.x * x0.y;
  g.yz = a0.yz * x12.xz + h.yz * x12.yw;

  return 130.0 * dot(m, g);
}


float chaseTime = 15.0;
float meetTime = 2.0;
float frequency = 0.2;
vec3 shipColor = vec3(0.8);
float maxShipRadius = 0.07;
int feedCycles = 5;
float foodSize = 0.02;

vec4 shipPosAt(float time) {
    float slot = floor(time / (chaseTime + meetTime));
    float remainingSlotTime = mod(time, (chaseTime + meetTime));
    float isInMeeting = step(chaseTime, remainingSlotTime);
    float x = ((slot + isInMeeting) * chaseTime) + remainingSlotTime * (1.0 - isInMeeting);
    return vec4(snoise(vec2(frequency * x, 0.0)), snoise(vec2(0.0, frequency * x)), isInMeeting, remainingSlotTime);
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Normalized pixel coordinates (from 0 to 1)
    float aspectRatio = iResolution.x / iResolution.y;
    vec2 uv = fragCoord/iResolution.xy * 2.0 - 1.0;
    uv.x = uv.x * aspectRatio;

    vec4 shipPos = shipPosAt(iTime);
    shipPos.x *= aspectRatio;
    float isEating = step(chaseTime + (meetTime / 2.0), shipPos.w);
    int timesEaten = int(mod(iTime / (chaseTime + meetTime), float(feedCycles)) + isEating);
    float shipRadius = maxShipRadius * (float(1 + timesEaten) / float(feedCycles));
    float isShipPixel = 1.0 - smoothstep(shipRadius - 0.01, shipRadius, distance(uv, shipPos.xy));

    float nextMeetingTime = (ceil(iTime / (chaseTime + meetTime)) + (shipPos.z * isEating)) * (chaseTime + meetTime);
    vec2 nextMeetingPos = shipPosAt(nextMeetingTime).xy;
    nextMeetingPos.x *= aspectRatio;
    float isFoodPixel = float(abs(nextMeetingPos.x - uv.x) < foodSize && abs(nextMeetingPos.y - uv.y) < foodSize);

    // Output to screen
    fragColor = vec4(mix(shipColor, vec3(0.0, 1.0, 0.0), 0.0) * isShipPixel,1.0)
        + vec4(vec3(0.4, 0.3, 0.0) * isFoodPixel, 1.0);
}
